    fragment: ['酒館的地板縫裡，夾著一張很舊的紙。是一張地圖的一角，筆跡很工整。', '角落寫著一行字：「海燕號的船長，請記得來接他。——公會長」', '{名}愣住了。公會長五十年前，就畫過這座港口。', '他在每一個等船的人旁邊，都寫了他們的名字。'],
    events: [
      { title: '等兒子的老太太', text: ['碼頭邊，一個老太太坐在小板凳上，一直往海的方向看。', '「我兒子說，今天會回來。」她說，「他叫什麼名字來著……」'],
        opts: [{ label: '陪她一起等', line: '等了一下午，船沒有來。可是老太太說了很多兒子小時候的事，越說越多。最後她說：「……他叫阿福。對，阿福。」她笑得好開心。', fx: { 士氣: 10, 褪色布: 1 } },
          { label: '把她畫進書裡（墨水 1）', line: '{名}把老太太畫下來，旁邊寫：「她在等阿福。」畫好的時候，老太太的衣服，好像多了一點顏色。', fx: { 墨水: -1, 士氣: 12 } }] },
      { title: '褪色的鐵匠鋪', text: ['港口的角落，有一間和石伯一模一樣的鐵匠鋪。打鐵的人，卻是一個年輕人。', '「客人要打什麼？」他說，「我的師父叫我在這裡等他回來。」'],
        opts: [{ label: '請他幫忙磨一磨武器（銀貝 30）', line: '年輕人磨得很仔細。他說，他的師父以前在一座叫鹽灣的島上打鐵。……{名}想了想，沒有告訴他石伯已經很老了。', fx: { 銀貝: -30, 士氣: 8, 古銅片: 1 } },
          { label: '問他師父叫什麼', line: '「石……什麼的。」年輕人想不起來。他把一包舊布塞給你們：「如果遇到他，幫我說一聲，我還在這裡。」', fx: { 褪色布: 2 } }] },
      { title: '寫錯名字的信箱', text: ['路邊有一個信箱，塞滿了信。每一封的收信人，名字都寫錯了。', '信箱上貼著一張紙：「請幫忙送信」。'],
        opts: [{ label: '一封一封改好名字（墨水 1）', line: '{名}改了一整個下午。改好的信，一封一封自己飛走了，往霧外面飛。', fx: { 墨水: -1, 士氣: 10, 守霧人: 3 } },
          { label: '拿走信封裡夾的舊船票', line: '信封裡夾著好幾張舊船票。你們收了起來。信箱，好像嘆了一口氣。', fx: { 舊船票: 2, 士氣: -3 } }] },
      { title: '沒有臉的貓', text: ['一隻灰色的貓蹲在屋頂上。牠沒有臉，可是你們知道，牠在看你們。', '牠的脖子上，掛著一個小小的名牌，字被磨掉了。'],
        opts: [{ label: '幫牠取一個新名字', line: '小鈴說：「就叫牠『小灰』吧。」貓跳下屋頂，在{名}的腳邊蹭了一下。牠的臉上，長出了一對眼睛。', fx: { 士氣: 10 } },
          { label: '丟一點糧食給牠（糧 2）', line: '貓叼走了乾糧。過了一會兒，牠叼回來一張船票，放在你們面前。', fx: { 糧: -2, 舊船票: 1, 士氣: 4 } }] },
      { title: '最後一班船的船票', text: ['售票口還開著。窗口裡的人說：「最後一班船。要買票嗎？」', '「去哪裡？」阿潮問。窗口裡的人說：「回家。」'],
        opts: [{ label: '買一張（銀貝 40）', line: '票上的目的地寫著「鹽灣島」。阿潮把票收進懷裡，說要留給他爸。', fx: { 銀貝: -40, 士氣: 12, 舊船票: 1 } },
          { label: '不買', line: '窗口的人點點頭，關上了小窗。窗戶上，倒映著一艘很小很小的船，正在往外開。', fx: { 士氣: 2, 墨水: 1 } }] },
      { title: '曬漁網的人', text: ['一排褪色的漁網，晾在碼頭上。網的另一頭，有一個人在拉。', '「幫個忙！」他說，「網太重了，我一個人拉不動。」'],
        opts: [{ label: '一起拉', line: '大家一起拉上來的，是一網發著光的魚。漁夫分了你們一半：「這是記得的魚。吃了，會想起一件小事。」', fx: { 糧: 5, 士氣: 6 } },
          { label: '幫他把網補好', line: '葛蘿補網的手很快。漁夫看著她，說：「妳補網的樣子，跟我老婆好像。」他送了你們一塊褪色的帆布。', fx: { 褪色布: 2, 士氣: 4 } }] },
    ],
    bps: ['海燕刀', '船票護符', '褪色布斗篷', '船票弓'],
