      enter: ['樹根讓開了。白花樹就在眼前，花一直在落，落不完。', '白花樹是這座島的首領。打倒它以後，還可以繼續探索。'],
      intro: ['白花樹的樹皮上，刻著島的名字。名字被刮掉了，只剩下一個小小的「蓮」字。', '樹下站著一個女人，手裡拿著一封信。她看著蓮笙，眼神很溫柔，像在看一個陌生人。', '「妳是誰家的孩子？」她說，「這座島，已經沒有孩子了。」', '花落得越來越快。整座島的影子，從樹下站了起來。', '「不要叫我的名字。」島說，「叫了，大家就會想起那一晚。」'],
