      text: ['畫室的角落，有一排長桌。桌前坐著幾個很老的人，低著頭，一筆一筆地畫。', '他們是五十年前，跟著公會長走進霧裡的製圖師。他們已經忘了自己為什麼要畫，可是手停不下來。', '其中一個老人抬起頭，看見{名}的筆，笑了一下：「新來的學徒？墨水在架子上，自己拿。」'],
      shop: { 糧: [6, 12], 燈油: [3, 13], 墨水: [4, 14], 藥草: [2, 17], 海靈露: [2, 15], 醒神香: [1, 19] },
